      var item = { cid: newCid(), area: area, title: i.title.slice(0, 200), created: Date.now(), attempts: 0 };
      if (i.all_day) { item.allDay = true; item.start = i.date; item.end = ymd(addDays(parseYmd(i.date), 1)); }
