  /* --- the screen --- */
  function trHead() {
    var w0 = sow(new Date());
    return { e: tr.view === "new" ? "TAROT · NEW READING" : tr.view === "reading" && trOpen() ? "TAROT · " + dLabel(parseYmd(trOpen().day)) : tr.view === "builder" ? "TAROT · MY SPREADS" : weekLabel(w0).replace(/^WEEK/, "TAROT · WEEK"), t: "TAROT" };
  }
