    mut(data);
    var item = { kind: "yard", name: y.name || "Apiary", notes: y.notes || "", day: y.day || null, data: data };
    if (y.id && String(y.id).indexOf("cid:") !== 0) item.id = y.id; else item.cid = y.id ? y.id.slice(4) : newCid();
