      esc(dn ? mlDName(dn) : past ? (small ? "" : "Not recorded") : small ? "" : "+ PLAN") + "</b>" + (small ? "" : "<span>" + (dn ? (dn.status === "eaten" ? "EATEN ✓" : "PLANNED") : past ? "TAP TO FILL IN" : "OPEN") + "</span>") + "</button>";
